/* Runtime for C generated by tools/mips2c (src/game/mips2c_rt.h). */
#include "mips2c_rt.h"

#include <stdio.h>
#include <stdlib.h>

u32 g_mips_sp;
u32 g_mips_v1;
int g_fast_render = 1; /* mips2c_rt.h, D70 */

/* R3000 division: no trap; x/0 gives hi = x, lo = -1 (x >= 0) or 1. */
void mips2c_div(u32 a, u32 b, u32 *hi, u32 *lo) {
  s32 x = (s32)a, y = (s32)b;
  if (y == 0) {
    *hi = a;
    *lo = x >= 0 ? 0xFFFFFFFFu : 1u;
  } else if (a == 0x80000000u && y == -1) {
    *hi = 0;
    *lo = 0x80000000u;
  } else {
    *hi = (u32)(x % y);
    *lo = (u32)(x / y);
  }
}

void mips2c_divu(u32 a, u32 b, u32 *hi, u32 *lo) {
  if (b == 0) {
    *hi = a;
    *lo = 0xFFFFFFFFu;
  } else {
    *hi = a % b;
    *lo = a / b;
  }
}

/* Unaligned word halves, little-endian. */
u32 mips2c_lwl(u32 old, u32 addr) {
  u32 w = M_U32(addr & ~3u), sh = (addr & 3u) * 8u;
  return (old & (0x00FFFFFFu >> sh)) | (w << (24u - sh));
}

u32 mips2c_lwr(u32 old, u32 addr) {
  u32 w = M_U32(addr & ~3u), sh = (addr & 3u) * 8u;
  return (old & ~(0xFFFFFFFFu >> sh)) | (w >> sh);
}

void mips2c_swl(u32 v, u32 addr) {
  u32 *p = (u32 *)(uintptr_t)(addr & ~3u), sh = (addr & 3u) * 8u;
  *p = (*p & ~(0xFFFFFFFFu >> (24u - sh))) | (v >> (24u - sh));
}

void mips2c_swr(u32 v, u32 addr) {
  u32 *p = (u32 *)(uintptr_t)(addr & ~3u), sh = (addr & 3u) * 8u;
  *p = (*p & ~(0xFFFFFFFFu << sh)) | (v << sh);
}

void mips2c_break(u32 code, u32 pc) {
  fprintf(stderr, "mips2c: break %u at %08X\n", code, pc);
  abort();
}

void mips2c_bad_jump(const char *unit, u32 target) {
  fprintf(stderr, "mips2c: %s: computed jump to %08X has no dispatch case\n", unit, target);
  abort();
}

void mips2c_fell_off(const char *unit) {
  fprintf(stderr, "mips2c: %s: fell off the end of the unit\n", unit);
  abort();
}

#if M2C_PROFILE
u32 g_m2c_prof[M2C_PROF_WORDS];

/* One u32 per instruction word from M2C_PROF_LO, to $SPYRO_M2C_PROF_OUT
 * (default m2c_prof.bin in the working directory). */
__attribute__((destructor)) static void m2c_prof_write(void) {
  const char *path = getenv("SPYRO_M2C_PROF_OUT");
  FILE *f = fopen(path ? path : "m2c_prof.bin", "wb");
  if (!f)
    return;
  fwrite(g_m2c_prof, sizeof g_m2c_prof, 1, f);
  fclose(f);
}
#endif
